-- 0002: contract terms extracted from executed PDFs (reviewable: every row cites file + page + quoted clauses).
create schema if not exists ref;
create table ref.contract_terms (
  document_id text primary key references raw.contract_register(document_id),
  contract_id text not null,
  customer_name text not null,
  billing_frequency text not null check (billing_frequency in ('annual','monthly')),
  billing_anchor_day smallint not null,
  service_start date not null,
  service_end_inclusive date not null,
  service_end_exclusive date not null,
  platform_fee numeric(14,2) not null,
  platform_fee_per text not null check (platform_fee_per in ('year','month')),
  annual_platform_commitment numeric(14,2) not null,
  included_runs_per_month integer not null,
  overage_rate_per_run numeric(10,4) not null,
  source_file text not null,
  source_page text not null default '1 / 1',
  evidence jsonb not null
);
create table ref.contract_amendment_terms (
  id serial primary key,
  amendment_document_id text not null references raw.contract_register(document_id),
  original_document_id text not null,
  term text not null,
  prior_value text,
  new_value text,
  numeric_value numeric(14,2),
  effective_from date,
  source_file text not null,
  source_page text not null default '1 / 1',
  evidence text not null
);
alter table ref.contract_terms enable row level security;
alter table ref.contract_amendment_terms enable row level security;
revoke all on schema ref from anon, authenticated;
revoke all on all tables in schema ref from anon, authenticated;
