('AM-OF-2026-157','OF-2026-157','included_runs_per_month','30000','45000',45000,'2026-10-16','AM-OF-2026-157.pdf','1 / 1','Monthly included workflow runs increase from 30,000 to 45,000 effective October 16, 2026 at 00:00 America/Denver.'),
('AM-OF-2026-157','OF-2026-157','oct_allowance_weighting',NULL,NULL,NULL,'2026-10-16','AM-OF-2026-157.pdf','1 / 1','For October, weight the prior allowance for October 1-15 and the amended allowance for October 16-31 by calendar days. Round the resulting allowance once to a whole run, half up. There is no retrospective change to earlier service.'),
('AM-OF-2026-157','OF-2026-157','overage_rate_per_run','0.40','0.40 (unchanged)',0.40,'2026-10-16','AM-OF-2026-157.pdf','1 / 1','The USD 0.40 overage rate and all other pricing terms remain unchanged.'),
('AM-OF-2026-157','OF-2026-157','monthly_platform_invoice','4000.00','4000.00 (unchanged)',4000.00,'2026-10-16','AM-OF-2026-157.pdf','1 / 1','The monthly platform invoice remains USD 4,000.00.'),
('AM-OF-2026-164','OF-2026-164','annual_platform_rate','48000.00','60000.00',60000.00,'2026-10-16','AM-OF-2026-164.pdf','1 / 1','Annual platform subscription rate increases from USD 48,000 to USD 60,000 effective October 16, 2026 at 00:00 America/Denver, for the remainder of the original term. No service before that date is repriced.'),
('AM-OF-2026-164','OF-2026-164','monthly_platform_invoice','4000.00','5000.00 from Nov 1',5000.00,'2026-11-01','AM-OF-2026-164.pdf','1 / 1','Monthly platform invoices are USD 5,000.00 from November 2026 through August 2027.'),
('AM-OF-2026-164','OF-2026-164','october_upgrade_catch_up',NULL,'526.03 additional',526.03,'2026-10-16','AM-OF-2026-164.pdf','1 / 1','October upgrade catch-up: USD 526.03, using USD 12,000 x 16 / 365, rounded half up. This additional October-service charge may be invoiced separately.'),
('AM-OF-2026-164','OF-2026-164','incremental_consideration_remaining_term',NULL,'10520.55 for 320 days',10520.55,'2026-10-16','AM-OF-2026-164.pdf','1 / 1','Incremental consideration for 320 remaining service days is USD 10,520.55. Original base consideration remains unchanged.'),
('AM-OF-2026-164','OF-2026-164','final_invoice_credit',NULL,'5.48',5.48,'2027-08-01','AM-OF-2026-164.pdf','1 / 1','The final platform invoice includes a USD 5.48 credit to reconcile the monthly billing convention to that amount.'),
